#include <stdio.h>
/*
 * ex01：多周期 CPU 的指令节拍统计
 * 为什么：单周期 CPU 每条指令都要等最慢那条走完（浪费），多周期把一条指令拆成
 *        取指/译码/执行/访存/写回若干机器周期，不同指令占的周期数不同，
 *        所以「平均 CPI」必须按指令类型分别加权统计，不能直接取 1。
 * 本程序：给定一段指令序列与各自的机器周期数，算出总周期与平均 CPI。
 */
typedef struct {
    const char *name;   /* 指令助记符 */
    const char *type;   /* 指令类型：运算 / 访存 / 转移 */
    int ticks;          /* 该指令占用的机器周期数 */
} Insn;

int main(void) {
    /* 一段典型的混合指令流：3 条运算 + 2 条访存 + 1 条转移 */
    Insn prog[] = {
        {"ADD  R1,R2,R3", "运算", 3},   /* 取指/执行/写回：3 周期 */
        {"LW   R4,0(R1)", "访存", 4},   /* 多一个访存周期：4 周期 */
        {"SUB  R5,R4,R2", "运算", 3},
        {"SW   0(R1),R5", "访存", 4},
        {"BEQ  R5,R0,L",  "转移", 3},
        {"ADD  R6,R4,R5", "运算", 3},
    };
    int n = (int)(sizeof(prog) / sizeof(prog[0]));
    int total = 0;

    printf("多周期 CPU 指令序列节拍统计（多周期模型）\n");
    printf("%-14s %-6s %s\n", "指令", "类型", "机器周期");
    for (int i = 0; i < n; i++) {
        printf("%-14s %-6s %d\n", prog[i].name, prog[i].type, prog[i].ticks);
        total += prog[i].ticks;      /* 累加真实周期数 */
    }
    /* 平均 CPI = 总周期数 / 指令条数；这里 >3，说明访存指令拉高了均值 */
    printf("指令条数=%d  总机器周期=%d  平均CPI=%.2f\n", n, total, (double)total / n);
    return 0;
}
